S=/workspace/nox/web/site; cd $S; export PATH=/workspace/nox/tools/node/bin:$PATH
rm -rf /tmp/w3sw; mkdir /tmp/w3sw; cd /tmp/w3sw; npm pack swiper 2>&1|tail -1; tar xzf *.tgz; cp package/swiper-bundle.min.js $S/vendor/swiper/swiper-bundle.umd.min.js; ls -la $S/vendor/swiper/swiper-bundle.umd.min.js; cd $S
echo '' | base64 -d | gunzip > nox-chat-x.js
echo '' | base64 -d | gunzip > nox-chat-x.css
echo '' | base64 -d | gunzip > nox-cinema-x.js
echo '' | base64 -d | gunzip > nox-music-x.js
echo '' | base64 -d | gunzip > nox-music-x.css
sed -i 's/nox-chat-x.js?v=[0-9]*/nox-chat-x.js?v=3/;s/nox-chat-x.css?v=[0-9]*/nox-chat-x.css?v=4/' chat.html
sed -i 's/nox-cinema-x.js?v=1/nox-cinema-x.js?v=2/' cinema.html; sed -i 's/nox-music-x.js?v=1/nox-music-x.js?v=2/;s/nox-music-x.css?v=1/nox-music-x.css?v=2/' music.html
echo '' | base64 -d | gunzip > /tmp/w3s.py
/workspace/nox/venv/bin/python /tmp/w3s.py musicA http://127.0.0.1:8091/web/music.html cinemaA http://127.0.0.1:8091/web/cinema.html 2>&1
